package com.grafkom.viewing3d; import org.joml.*; public final class Camera3D {private final Vector3f target=new Vector3f(0,0.5f,0);private float azimuth=35,elevation=24,radius=7;public void orbit(float da,float de){azimuth+=da;elevation=java.lang.Math.max(-10,java.lang.Math.min(80,elevation+de));}public void zoom(float amount){radius=java.lang.Math.max(3,java.lang.Math.min(14,radius+amount));}public Vector3f position(){float a=(float)java.lang.Math.toRadians(azimuth),e=(float)java.lang.Math.toRadians(elevation);return new Vector3f((float)(radius*java.lang.Math.cos(e)*java.lang.Math.sin(a)),target.y+(float)(radius*java.lang.Math.sin(e)),(float)(radius*java.lang.Math.cos(e)*java.lang.Math.cos(a)));}public Matrix4f view(){return new Matrix4f().lookAt(position(),target,new Vector3f(0,1,0));}}
